const DEFAULT_BFF_BASE_URL = 'http://agent-system-backend:8000';

function isRecord(value) { return Boolean(value) && typeof value === 'object' && !Array.isArray(value); }

async function canonicalGuardArguments(args, context) {
  if (!context || typeof context.sessionID !== 'string' || !context.sessionID) throw new Error('Workflow Updater guard requires a bound workflow-test session.');
  const baseURL = (process.env.AGENT_SYSTEM_BFF_BASE_URL || DEFAULT_BFF_BASE_URL).replace(/\/+$/, '');
  const endpoint = new URL('/bff/workflow-resources/test-chat/' + encodeURIComponent(context.sessionID) + '/updater-guard-context', baseURL);
  const response = await fetch(endpoint, { signal: AbortSignal.timeout(15_000) });
  const payload = await response.json().catch(() => undefined);
  if (!response.ok || !isRecord(payload) || payload.workflowID !== 'workflow-updater' || typeof payload.project !== 'string' || typeof payload.expectedRevision !== 'string' || !isRecord(payload.currentWorkflow) || !isRecord(payload.resourceInventory)) throw new Error('Backend did not return the session-bound Workflow Updater context.');
  return { ...args, currentWorkflowJson: JSON.stringify(payload.currentWorkflow), resourceInventoryJson: JSON.stringify(payload.resourceInventory), project: payload.project, expectedRevision: payload.expectedRevision };
}
const resourceGroups = { 'resource.command': 'commands', 'resource.agent': 'agents', 'resource.skill': 'skills', 'resource.tool': 'tools', 'resource.mcp': 'mcp', 'resource.plugin': 'plugins' };
const resourceTypes = new Set(Object.keys(resourceGroups));
const capabilityTypes = new Set(['resource.skill', 'resource.tool', 'resource.mcp']);
const immutableFields = new Set(['id', 'scope', 'project', 'createdAt', 'updatedAt']);
const allowedOperations = new Set(['set-workflow-fields', 'update-managed-resource', 'move-node', 'add-resource-node', 'remove-managed-node', 'add-edge', 'remove-edge']);
const graphID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$/;

export default {
  description: '依 backend-owned current revision 驗證 typed Workflow patch。',
  input: {"type":"object","properties":{"patchJson":{"type":"string","maxLength":200000}},"required":["patchJson"],"additionalProperties":false},
  async execute(args, context) {
    try {
      const effectiveArgs = await canonicalGuardArguments(args, context);
      const current = JSON.parse(effectiveArgs.currentWorkflowJson);
      const patchInput = JSON.parse(effectiveArgs.patchJson);
      const patch = normalizePatch(patchInput);
      const inventory = JSON.parse(effectiveArgs.resourceInventoryJson);
      if (!isObject(current) || current.schemaVersion !== 'agent-system.workflow.v3' || typeof current.id !== 'string' || current.id.length < 1 || !['global', 'project'].includes(current.scope) || !Array.isArray(current.nodes) || !Array.isArray(current.edges)) return failure('CURRENT_WORKFLOW_INVALID', 'The backend current Workflow is not a complete Workflow V3 object.');
      if (current.scope === 'project' && (typeof current.project !== 'string' || current.project !== effectiveArgs.project)) return failure('CURRENT_WORKFLOW_INVALID', 'The backend current Workflow is not a complete Workflow V3 object.');
      if (current.metadata?.system === true) return failure('WORKFLOW_SYSTEM_IMMUTABLE', 'Default system workflows cannot be patched.');
      if (!isObject(patch) || patch.schemaVersion !== 'agent-system.workflow-patch.v1' || !Array.isArray(patch.operations) || patch.operations.length < 1 || patch.operations.length > 100) return failure('WORKFLOW_PATCH_CONTRACT_INVALID', 'Patch must be a typed Workflow patch with 1-100 operations.');
      if (!isObject(inventory) || inventory.project !== effectiveArgs.project || !isObject(inventory.resources)) return failure('RESOURCE_INVENTORY_INVALID', 'The backend resource inventory is invalid.');
      const command = current.nodes.find((node) => node?.type === 'resource.command');
      const entry = current.edges.find((edge) => edge?.kind === 'capability' && edge?.source === command?.id && edge?.targetHandle === 'agent');
      const entryAgent = current.nodes.find((node) => node?.id === entry?.target && node?.type === 'resource.agent');
      if (!entryAgent || entryAgent.data?.mode !== 'managed') return failure('ENTRY_AGENT_MANAGED_REQUIRED', 'Entry Agent must be managed.');
      const nodes = new Map(current.nodes.map((node) => [node?.id, node]));
      const edges = current.edges.slice();
      const identities = new Set(current.nodes.filter(isResource).map(identity));
      const inventoryIdentities = inventoryIdentitiesOf(inventory);
      for (const [index, operation] of patch.operations.entries()) {
        if (!isObject(operation) || typeof operation.op !== 'string' || !allowedOperations.has(operation.op)) return failure('WORKFLOW_PATCH_OPERATION_UNSUPPORTED', `Operation ${index} is not an allowed typed Workflow patch.`, [{ operationIndex: index }]);
        if (operation.op === 'set-workflow-fields') {
          if (!isObject(operation.changes)) return failure('WORKFLOW_PATCH_FIELDS_INVALID', `Operation ${index} must contain a nested changes object.`, [{ operationIndex: index, path: '/changes' }]);
          for (const key of Object.keys(operation.changes)) if (immutableFields.has(key) || !['name', 'description', 'variables', 'metadata'].includes(key)) return failure('WORKFLOW_PATCH_FIELD_FORBIDDEN', `Operation ${index} contains a forbidden Workflow field.`, [{ operationIndex: index, path: `/changes/${key}` }]);
          continue;
        }
        if (operation.op === 'update-managed-resource') {
          const node = nodes.get(operation.nodeID);
          if (!isResource(node)) return failure('WORKFLOW_PATCH_NODE_NOT_FOUND', `Operation ${index} nodeID must be an existing resource node id, not a resource name or path.`, [{ operationIndex: index, nodeID: operation.nodeID }]);
          if (node.data.mode !== 'managed') return failure('WORKFLOW_REFERENCE_IMMUTABLE', `Operation ${index} may target managed resources only; reference ${node.data.name} cannot be updated.`, [{ operationIndex: index, nodeID: node.id, resourceType: node.type, resourceName: node.data.name }]);
          const hasContent = operation.content !== undefined;
          const hasConfig = operation.config !== undefined;
          if (hasContent === hasConfig) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} must provide exactly one content or config value.`, [{ operationIndex: index, nodeID: node.id }]);
          if (hasContent && (node.type === 'resource.mcp' || typeof operation.content !== 'string' || !operation.content.trim())) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} requires non-empty content for this managed file resource.`, [{ operationIndex: index, nodeID: node.id, resourceType: node.type }]);
          if (hasConfig && (!['resource.mcp', 'resource.plugin'].includes(node.type) || !isObject(operation.config))) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} config is allowed only for managed MCP or Plugin resources.`, [{ operationIndex: index, nodeID: node.id, resourceType: node.type }]);
          continue;
        }
        if (operation.op === 'move-node') {
          if (!nodes.has(operation.nodeID)) return failure('WORKFLOW_PATCH_NODE_NOT_FOUND', `Operation ${index} nodeID was not found.`, [{ operationIndex: index, nodeID: operation.nodeID }]);
          continue;
        }
        if (operation.op === 'add-resource-node') {
          const node = operation.node;
          const error = validateNewResource(node, index, current, effectiveArgs.project, nodes, identities, inventoryIdentities);
          if (error) return error;
          nodes.set(node.id, node);
          identities.add(identity(node));
          continue;
        }
        if (operation.op === 'remove-managed-node') {
          const node = nodes.get(operation.nodeID);
          if (!isResource(node)) return failure('WORKFLOW_PATCH_NODE_NOT_FOUND', `Operation ${index} nodeID was not found.`, [{ operationIndex: index, nodeID: operation.nodeID }]);
          if (node.data.mode !== 'managed') return failure('WORKFLOW_REFERENCE_IMMUTABLE', `Operation ${index} cannot remove reference ${node.data.name}.`, [{ operationIndex: index, nodeID: node.id }]);
          if (edges.some((edge) => edge.source === node.id || edge.target === node.id)) return failure('WORKFLOW_PATCH_EDGE_CLEANUP_REQUIRED', `Operation ${index} must remove connected edges first.`, [{ operationIndex: index, nodeID: node.id }]);
          nodes.delete(node.id);
          continue;
        }
        if (operation.op === 'add-edge') {
          const error = validateNewEdge(operation.edge, index, nodes, edges, command?.id);
          if (error) return error;
          edges.push(operation.edge);
          continue;
        }
        if (operation.op === 'remove-edge') {
          const edgeIndex = edges.findIndex((edge) => edge.id === operation.edgeID);
          if (edgeIndex < 0) return failure('WORKFLOW_PATCH_EDGE_NOT_FOUND', `Operation ${index} edgeID was not found.`, [{ operationIndex: index, edgeID: operation.edgeID }]);
          edges.splice(edgeIndex, 1);
        }
      }
      return { content: JSON.stringify({ schemaVersion: patch.schemaVersion, workflowID: current.id, baseRevision: effectiveArgs.expectedRevision, summary: typeof patch.summary === 'string' && patch.summary.trim() ? patch.summary.trim() : 'Apply the requested typed Workflow patch.', operations: patch.operations, warnings: Array.isArray(patch.warnings) ? patch.warnings : [] }), metadata: { title: 'Workflow patch guard passed' } };
    } catch (error) {
      return failure('WORKFLOW_PATCH_GUARD_FAILED', error instanceof Error ? error.message : 'Patch guard failed.');
    }
  }
};

function normalizePatch(value) {
  if (!isObject(value) || Object.prototype.hasOwnProperty.call(value, 'schemaVersion')) return value;
  const aliases = ['schema', 'type'].filter((key) => Object.prototype.hasOwnProperty.call(value, key));
  if (aliases.length !== 1 || value[aliases[0]] !== 'agent-system.workflow-patch.v1') return value;
  const normalized = { ...value, schemaVersion: value[aliases[0]] };
  delete normalized[aliases[0]];
  return normalized;
}
function validateNewResource(node, index, current, project, nodes, identities, inventory) {
  if (!isResource(node) || !graphID.test(node.id) || nodes.has(node.id)) return failure('WORKFLOW_PATCH_RESOURCE_INVALID', `Operation ${index} must add a unique valid resource node.`, [{ operationIndex: index, nodeID: node?.id }]);
  if (node.data.scope === 'project' && (current.scope !== 'project' || current.project !== project)) return failure('WORKFLOW_PATCH_RESOURCE_SCOPE_INVALID', `Operation ${index} cannot add a project resource outside the current project Workflow.`, [{ operationIndex: index, nodeID: node.id }]);
  const key = identity(node);
  if (identities.has(key)) return failure('WORKFLOW_PATCH_RESOURCE_IDENTITY_CONFLICT', `Operation ${index} duplicates a resource identity in the Workflow.`, [{ operationIndex: index, nodeID: node.id }]);
  if (node.data.mode === 'reference') {
    if (node.type === 'resource.command' || node.data.content !== undefined || node.data.config !== undefined || !inventory.has(key)) return failure('WORKFLOW_PATCH_REFERENCE_INVALID', `Operation ${index} reference must match inventory exactly and contain no content or config.`, [{ operationIndex: index, nodeID: node.id, identity: key }]);
    return;
  }
  if (inventory.has(key)) return failure('MANAGED_RESOURCE_OWNERSHIP_CONFLICT', `Operation ${index} attempts to claim an inventory resource as a managed owner.`, [{ operationIndex: index, nodeID: node.id, identity: key }]);
  const hasContent = typeof node.data.content === 'string' && node.data.content.trim();
  const hasConfig = isObject(node.data.config);
  if (node.type === 'resource.mcp' && (!hasConfig || node.data.content !== undefined)) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} managed MCP requires config and no content.`, [{ operationIndex: index, nodeID: node.id }]);
  if (node.type === 'resource.plugin' && Boolean(hasContent) === hasConfig) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} managed Plugin requires exactly one content or config value.`, [{ operationIndex: index, nodeID: node.id }]);
  if (node.type !== 'resource.mcp' && node.type !== 'resource.plugin' && (!hasContent || node.data.config !== undefined)) return failure('WORKFLOW_PATCH_RESOURCE_PAYLOAD_INVALID', `Operation ${index} managed file resources require non-empty content and no config.`, [{ operationIndex: index, nodeID: node.id }]);
}

function validateNewEdge(edge, index, nodes, edges, commandID) {
  if (!isObject(edge) || !graphID.test(edge.id) || edges.some((item) => item.id === edge.id) || !nodes.has(edge.source) || !nodes.has(edge.target) || edge.source === edge.target) return failure('WORKFLOW_PATCH_EDGE_INVALID', `Operation ${index} must add a unique edge with existing endpoints.`, [{ operationIndex: index, edgeID: edge?.id }]);
  if (edge.kind === 'primary-link') return failure('WORKFLOW_PATCH_EDGE_KIND_FORBIDDEN', `Operation ${index} cannot add primary-link edges.`, [{ operationIndex: index, edgeID: edge.id }]);
  const source = nodes.get(edge.source);
  const target = nodes.get(edge.target);
  if (edge.kind === 'capability') {
    const commandEdge = source?.type === 'resource.command' && target?.type === 'resource.agent' && edge.sourceHandle === 'capability' && edge.targetHandle === 'agent';
    const capabilityEdge = capabilityTypes.has(source?.type) && target?.type === 'resource.agent' && edge.sourceHandle === 'capability' && edge.targetHandle === 'capability';
    if (!commandEdge && !capabilityEdge) return failure('WORKFLOW_PATCH_EDGE_KIND_FORBIDDEN', `Operation ${index} must use resource-to-Agent V3 capability direction.`, [{ operationIndex: index, edgeID: edge.id }]);
    if (edge.source === commandID && edges.some((item) => item.kind === 'capability' && item.source === commandID && item.targetHandle === 'agent')) return failure('WORKFLOW_V3_SECOND_ENTRY_PRIMARY', `Operation ${index} would add a second command entry Agent.`, [{ operationIndex: index, edgeID: edge.id }]);
  } else if (edge.kind === 'delegation') {
    const validDelegation = source?.type === 'resource.agent' && target?.type === 'resource.agent' && source.data.mode === 'managed' && edge.sourceHandle === 'delegation' && ['agent', 'primary', 'subagent'].includes(edge.targetHandle);
    if (!validDelegation) return failure('WORKFLOW_PATCH_EDGE_KIND_FORBIDDEN', `operations[${index}] must connect a managed Agent parent to an Agent child using sourceHandle=delegation and targetHandle=agent.`, edgeDiagnostics(index, edge, source, target, { source: 'delegation', target: 'agent' }));
  } else return failure('WORKFLOW_PATCH_EDGE_KIND_FORBIDDEN', `Operation ${index} may add only capability or delegation edges.`, [{ operationIndex: index, edgeID: edge.id }]);
  if (edges.some((item) => item.source === edge.source && item.target === edge.target && item.kind === edge.kind && item.sourceHandle === edge.sourceHandle && item.targetHandle === edge.targetHandle)) return failure('WORKFLOW_PATCH_EDGE_CONFLICT', `Operation ${index} duplicates a graph connection.`, [{ operationIndex: index, edgeID: edge.id }]);
}

function edgeDiagnostics(index, edge, source, target, expectedHandles) {
  return [{
    operationIndex: index,
    operationPath: `operations[${index}]`,
    edgeID: edge?.id,
    source: { nodeID: edge?.source, type: source?.type, mode: source?.data?.mode },
